// 예시 보고서 — 자연관찰 연습 세트마다 「잘 쓴 보고서」 한 벌(원장 2026-10-25: 보고서 예시에 관찰그림이 그려져 있어야 한다).
// 관찰그림은 data/pencil-svg.js로 그린 연필 그림이고, 화면에서는 손에 든 연필이 선을 하나씩 그려 간다(observe-sample.js).
// 글은 대회 최우수 보고서의 「쓰는 방식」(관찰한 사실 → 손으로 확인한 것 → 추정, 본 것과 생각한 것을 나눔)을 따랐고 문장은 전부 새로 썼다.
// 아이에게 보여 주는 목적: 베끼기가 아니라 「그림엔 무엇을 표시하고, 글엔 무엇을 쓰는가」. 그래서 이름은 번호로 두고 추정에는 「~로 추정된다」를 붙였다.
import { pencilSvg, shapes as S } from './pencil-svg.js';
import { STROKES } from './sketch-strokes.js';
import { PLACES as LP } from '../scenes/specimens-litter.js';
import { PLACES as BP } from '../scenes/specimens-beach.js';

// 관찰그림 = 연필 스케치(원장 2026-10-25: 「스케치 느낌이 나야지」 — 도형으로 그린 그림을 거절).
// 스케치 원본은 3D 표본 렌더(곤충은 실사 사진) → tools/sketch/build.py. 이름표·확대 원·자는 그 위에 연필 SVG로 더한다.
// fig(제목, 스케치 이름, [x, y, 너비, 높이], (d, P, dr) => [조각…]) — P(px, py)는 스케치 픽셀 → 그림 좌표(이름표가 가리킬 자리).
const fig = (title, key, [bx, by, bw, bh], more, seed = 3) => pencilSvg(400, 300, (d) => {
  const k = STROKES[key], dw = Math.min(bw, (bh * k.w) / k.h), x = bx + (bw - dw) / 2, y = by + (bh - (dw * k.h) / k.w) / 2;
  const dr = d.drawing(key, +x.toFixed(1), +y.toFixed(1), +dw.toFixed(1));
  return [d.text(14, 22, title, { size: 14 }), ...more(d, (px, py) => dr.at(px, py), dr)];
}, { seed });

